    private long subsetHash(org.objectweb.asm.Type t, ClassNode cn) {
        long h = t.hashCode();
        BASet<MethodNode> methods = new BASet<MethodNode>(methodNodeComparator, cn.methods);
        for (MethodNode m : methods) {
