                Type rt = returnType(m);
                h = MagicNumbers.hashStepLong(h, MagicNumbers.M, rt.hashCode());
                Type[] pts = argumentTypes(m);
                h = MagicNumbers.hashArrayLong(pts, h);
            }
        }
        return h;
    }

